// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Receiver rcv;

    function setUp() public { c = new SimpleWallet(); rcv = new Receiver(); }

    function testFuzz_property(uint256 amount, uint256 value, bytes memory data) public {
        amount = bound(amount, 0, 1e24);
        vm.deal(address(c), amount);
        value = bound(value, 0, amount);
        vm.prank(address(this));
        c.sendMoney(address(rcv), value, data);
        assertEq(address(c).balance, amount - value);
    }
}

contract Receiver {
    uint256 public callCount;
    uint256 public lastValue;
    fallback() external payable {
        callCount++;
        lastValue = msg.value;
    }
}
